338	
339	const PAGE_SCRIPT = `
340	(function () {
341	  var form = document.getElementById('product-form');
342	  var nameInput = document.getElementById('product-name');
343	  var specsBox = document.getElementById('specs');
344	  var statusBox = document.getElementById('form-status');
345	  var submitBtn = document.getElementById('submit-btn');
346	  var addSpecBtn = document.getElementById('add-spec');
347	  var submitting = false;
348	
349	  function attrRowHtml() {
350	    return '<div class="attr-row">'
351	      + '<input type="text" data-attr-name placeholder="属性名称，如：颜色" maxlength="100">'
352	      + '<input type="text" data-attr-value placeholder="属性值，如：红色" maxlength="200">'
353	      + '<button type="button" class="remove-attr">删除属性</button>'
354	      + '<span class="err" data-err="attrName"></span>'
355	      + '<span class="err" data-err="attrValue"></span>'
356	      + '</div>';
357	  }
358	  function specCardHtml() {
359	    return '<fieldset class="spec" data-spec>'
360	      + '<legend data-spec-no>规格 1</legend>'
361	      + '<div class="attrs" data-attrs>' + attrRowHtml() + '</div>'
362	      + '<p><button type="button" class="add-attr">添加属性</button> '
363	      + '<button type="button" class="remove-spec">删除此规格</button></p>'
364	      + '<p class="field"><label>售价 <input type="text" inputmode="decimal" data-price placeholder="如 10.00"></label>'
365	      + '<span class="err" data-err="price"></span></p>'
366	      + '<p class="field"><label>库存 <input type="text" inputmode="numeric" data-stock placeholder="非负整数"></label>'
367	      + '<span class="err" data-err="stock"></span></p>'
368	      + '<p class="err" data-err="spec"></p>'
369	      + '<p class="err" data-err="attributes"></p>'
370	      + '</fieldset>';
371	  }
372	  function refreshNumbers() {
373	    var cards = specsBox.querySelectorAll('[data-spec]');
374	    for (var i = 0; i < cards.length; i++) {
375	      cards[i].querySelector('[data-spec-no]').textContent = '规格 ' + (i + 1);
376	    }
377	  }
378	  function addSpec() {
379	    if (submitting) return;
380	    specsBox.insertAdjacentHTML('beforeend', specCardHtml());
381	    refreshNumbers();
382	  }
383	  specsBox.addEventListener('click', function (event) {
384	    if (submitting) return; // 等待保存结果期间不允许添加或删除规格、属性
385	    var target = event.target;
386	    if (!(target instanceof Element)) return;
387	    if (target.classList.contains('add-attr')) {
388	      var card = target.closest('[data-spec]');
389	      card.querySelector('[data-attrs]').insertAdjacentHTML('beforeend', attrRowHtml());
390	    } else if (target.classList.contains('remove-attr')) {
391	      var row = target.closest('.attr-row');
392	      if (row.parentElement.querySelectorAll('.attr-row').length > 1) row.remove();
393	    } else if (target.classList.contains('remove-spec')) {
394	      if (specsBox.querySelectorAll('[data-spec]').length > 1) {
395	        target.closest('[data-spec]').remove();
396	        refreshNumbers();
397	      }
398	    }
399	  });
400	  document.getElementById('add-spec').addEventListener('click', addSpec);
401	
402	  function clearErrors() {
403	    statusBox.className = '';
404	    statusBox.textContent = '';
405	    var slots = form.querySelectorAll('.err');
406	    for (var i = 0; i < slots.length; i++) slots[i].textContent = '';
407	    var invalids = form.querySelectorAll('.invalid');
408	    for (var j = 0; j < invalids.length; j++) invalids[j].classList.remove('invalid');
409	  }
410	  function setSlotError(container, key, text, inputKey) {
411	    var slot = container.querySelector('[data-err="' + key + '"]');
412	    if (slot) slot.textContent = text;
413	    if (inputKey) {
414	      var input = container.querySelector('[' + inputKey + ']');
415	      if (input) input.classList.add('invalid');
416	    }
417	  }
418	  function showFailure(message, details) {
419	    statusBox.className = 'error';
420	    statusBox.textContent = message + '（已保留填写内容，修正后可再次提交）';
421	    if (!details) return;
422	    details.forEach(function (detail) {
423	      if (detail.field === 'name') {
424	        setSlotError(form, 'name', detail.message, 'data-name-input');
425	        return;
426	      }
427	      var cards = specsBox.querySelectorAll('[data-spec]');
428	      var card = cards[detail.specIndex];
429	      if (!card) return;
430	      if (detail.field === 'attrName' || detail.field === 'attrValue') {
431	        var rows = card.querySelectorAll('.attr-row');
432	        var row = rows[detail.attributeIndex];
433	        if (row) {
434	          var key = detail.field === 'attrName' ? 'attrName' : 'attrValue';
435	          var inputKey = detail.field === 'attrName' ? 'data-attr-name' : 'data-attr-value';
436	          setSlotError(row, key, detail.message, inputKey);
437	        }
438	        return;
439	      }
440	      var inputKey = detail.field === 'price' ? 'data-price' : detail.field === 'stock' ? 'data-stock' : null;
441	      setSlotError(card, detail.field, detail.message, inputKey);
442	    });
443	  }
444	  function showSaveError() {
445	    statusBox.className = 'error';
446	    statusBox.textContent = '保存失败，商品未保存，请稍后重试。已有商品没有受到影响，填写内容仍然保留。';
447	  }
448	
449	  // 等待保存结果期间：锁定所有输入与增删按钮，页面内容必须与本次发送的载荷保持一致。
450	  function setFormLocked(locked) {
451	    nameInput.disabled = locked;
452	    addSpecBtn.disabled = locked;
453	    var controls = specsBox.querySelectorAll('input, button');
454	    for (var i = 0; i < controls.length; i++) controls[i].disabled = locked;
455	  }
456	  function setSaving() {
457	    statusBox.className = 'saving';
458	    statusBox.textContent = '正在保存……';
459	  }
460	  // 请求结束且未跳转时：结束等待状态，恢复填写与增删操作，填写内容原样保留。
461	  function restoreForm() {
462	    submitting = false;
463	    submitBtn.disabled = false;
464	    setFormLocked(false);
465	  }
466	
467	  function collectPayload() {
468	    var payload = { name: nameInput.value, specs: [] };
469	    var cards = specsBox.querySelectorAll('[data-spec]');
470	    for (var i = 0; i < cards.length; i++) {
471	      var card = cards[i];
472	      var attributes = [];
473	      var rows = card.querySelectorAll('.attr-row');
474	      for (var j = 0; j < rows.length; j++) {
475	        attributes.push({
476	          name: rows[j].querySelector('[data-attr-name]').value,
477	          value: rows[j].querySelector('[data-attr-value]').value
478	        });
479	      }
480	      var stockRaw = card.querySelector('[data-stock]').value;
481	      var stock;
482	      if (stockRaw === '') {
483	        stock = null;
484	      } else if (/^\\d+$/.test(stockRaw) && Number(stockRaw) <= Number.MAX_SAFE_INTEGER) {
485	        stock = Number(stockRaw);
486	      } else {
487	        stock = stockRaw;
488	      }
489	      payload.specs.push({
490	        attributes: attributes,
491	        price: card.querySelector('[data-price]').value,
492	        stock: stock
493	      });
494	    }
495	    return payload;
496	  }
497	
498	  addSpec();
499	  form.addEventListener('submit', function (event) {
500	    event.preventDefault();
501	    if (submitting) return; // 等待期间再次提交（含回车）直接忽略
502	    submitting = true;
503	    clearErrors();
504	    submitBtn.disabled = true;
505	    setFormLocked(true);
506	    setSaving();
507	    fetch('/api/products', {
508	      method: 'POST',
509	      headers: { 'content-type': 'application/json' },
510	      body: JSON.stringify(collectPayload())
511	    }).then(function (response) {
512	      return response.json().catch(function () { return null; }).then(function (data) {
513	        return { status: response.status, data: data };
514	      });
515	    }).then(function (result) {
516	      if (result.status === 201 && result.data) {
517	        window.location.assign('/');
518	        return; // 成功后整页跳转，保持等待状态直到离开
519	      }
520	      restoreForm();
521	      if (result.status === 400 && result.data) {
522	        showFailure(result.data.error || '提交内容不符合要求', result.data.details);
523	      } else {
524	        showSaveError();
525	      }
526	    }).catch(function () {
527	      restoreForm();
528	      showSaveError();
529	    });
530	  });
531	})();
532	`;
533	
534	function renderPage(products: Product[]): string {
535	  return `<!doctype html>
536	<html lang="zh-CN">
537	<head>
538	<meta charset="utf-8">
539	<meta name="viewport" content="width=device-width,initial-scale=1">
540	<title>Cartwell · 商品目录与购物订单</title>
541	<style>${PAGE_STYLE}</style>
542	</head>
543	<body>
544	<main>
545	<h1>Cartwell</h1>
546	<p>商品目录与购物订单</p>
547	<section>
548	<h2>商品列表</h2>
