560	</form>
561	</section>
562	<p><a href="/api/products">查看商品列表接口</a> · <a href="/health">服务状态</a></p>
563	</main>
564	<script>${PAGE_SCRIPT}</script>
565	</body>
566	</html>`;
567	}
568	
569	const ERROR_PAGE = (message: string): string => `<!doctype html>
570	<html lang="zh-CN"><meta charset="utf-8"><title>Cartwell · 出错了</title>
571	<body style="font-family:system-ui,sans-serif;max-width:40rem;margin:3rem auto;padding:0 1rem">
572	<h1>暂时无法读取商品</h1><p>${escapeHtml(message)}</p><p><a href="/">返回首页重试</a></p></body></html>`;
573	
574	// ---------- HTTP 服务 ----------
575	
576	function respond(res: ServerResponse, status: number, value: unknown, html = false, allow?: string): void {
577	  if (res.destroyed || res.writableEnded) return; // 客户端可能已在读取请求体期间断开
578	  const body = html ? String(value) : JSON.stringify(value);
579	  const headers: Record<string, string> = {
580	    'content-type': html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
581	    'content-length': String(Buffer.byteLength(body)),
582	  };
583	  if (status === 405 && allow) headers.allow = allow;
584	  res.writeHead(status, headers);
585	  res.end(body);
586	}
587	
588	function readJsonBody(req: IncomingMessage): Promise<unknown> {
589	  return new Promise((resolve, reject) => {
590	    let size = 0;
591	    const chunks: Buffer[] = [];
592	    let bodyTooLarge = false;
593	    let settled = false;
594	    const fail = (reason: 'too-large' | 'invalid-json'): void => {
595	      if (settled) return;
596	      settled = true;
597	      reject(new Error(reason));
598	    };
599	    req.on('data', (chunk: Buffer) => {
600	      size += chunk.length;
601	      if (bodyTooLarge) return; // 已确认超限，继续排空后续数据即可
602	      // 超限只标记、停止缓存，绝不销毁连接：未读完的请求数据会导致随后写出的响应被
603	      // TCP RST，客户端只能看到连接重置。继续读完整个请求体后再在 'end' 中拒绝。
604	      if (size > MAX_BODY_BYTES) {
605	        bodyTooLarge = true;
606	        chunks.length = 0;
607	        return;
608	      }
609	      chunks.push(chunk);
610	    });
611	    req.on('end', () => {
612	      if (bodyTooLarge) {
613	        fail('too-large');
614	        return;
615	      }
616	      try {
617	        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));
618	      } catch {
619	        fail('invalid-json');
620	      }
621	    });
622	    req.on('error', () => fail(bodyTooLarge ? 'too-large' : 'invalid-json'));
623	  });
624	}
625	
626	const ALLOWED_METHODS: Record<string, string[]> = {
627	  '/': ['GET'],
628	  '/health': ['GET'],
629	  '/api/products': ['GET', 'POST'],
630	};
631	
632	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
633	  let route: string;
634	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; } catch { respond(res, 400, { error: 'invalid request path' }); return; }
635	
636	  const allowed = ALLOWED_METHODS[route];
637	  if (!allowed) { respond(res, 404, { error: 'not found' }); return; }
638	  const method = req.method ?? '';
639	  if (!allowed.includes(method)) {
640	    respond(res, 405, { error: 'method not allowed', allowed }, false, allowed.join(', '));
641	    return;
642	  }
643	
644	  if (route === '/health') { respond(res, 200, { status: 'ok', product: PRODUCT }); return; }
645	
646	  if (route === '/' && method === 'GET') {
647	    try {
648	      respond(res, 200, renderPage(readProducts()), true);
649	    } catch {
650	      respond(res, 500, ERROR_PAGE('商品数据暂时无法读取，已有记录未被修改。'), true);
651	    }
652	    return;
653	  }
654	
655	  if (route === '/api/products' && method === 'GET') {
656	    try {
657	      respond(res, 200, { [RESOURCE]: readProducts() });
658	    } catch {
659	      respond(res, 500, { error: 'unable to read products' });
660	    }
661	    return;
662	  }
663	
664	  // POST /api/products
665	  readJsonBody(req).then((input) => {
666	    const result = validateProduct(input);
667	    if (!result.ok) {
668	      respond(res, 400, { error: '商品校验未通过，未创建任何记录', details: result.errors });
669	      return;
670	    }
671	    const product: Product = {
672	      id: randomUUID(),
673	      name: result.name,
674	      specs: result.specs,
675	      createdAt: new Date().toISOString(),
676	    };
677	    try {
678	      const products = readProducts();
679	      products.unshift(product); // 新创建的商品排在最前
680	      saveProducts(products);
681	    } catch {
682	      respond(res, 500, { error: '商品保存失败，请稍后重试；已有商品未受影响' });
683	      return;
684	    }
685	    respond(res, 201, product);
686	  }).catch((error: Error) => {
687	    if (error.message === 'too-large') {
688	      respond(res, 400, {
689	        error: `请求体超过 ${MAX_BODY_BYTES} 字节的大小限制，商品没有保存`,
690	        limitBytes: MAX_BODY_BYTES,
691	      });
692	    } else {
693	      respond(res, 400, { error: '请求内容不是合法的 JSON' });
694	    }
695	  });
696	});
697	
698	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
699	server.listen(port, host, (): void => {
700	  const address = server.address();
701	  if (address && typeof address !== 'string') {
702	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
703	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
704	  }
705	});
706	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
