101	      let index = 0;
102	      const sendNext = (): void => {
103	        if (index >= chunks.length) { client.end(); return; }
104	        client.write(chunks[index++]);
105	        setImmediate(sendNext);
106	      };
107	      sendNext();
108	    });
109	    client.on('data', (chunk) => received.push(chunk));
110	    client.on('error', (error) => reject(error));
111	    client.on('close', (hadError) => {
112	      const raw = Buffer.concat(received);
113	      const split = raw.indexOf('\r\n\r\n');
114	      const head = split >= 0 ? raw.subarray(0, split).toString('utf8') : '';
115	      const statusLine = head.split('\r\n')[0] ?? '';
116	      const statusCode = Number(statusLine.slice(9, 12)) || 0;
117	      let body = split >= 0 ? raw.subarray(split + 4) : Buffer.alloc(0);
