146	    const piece = body.subarray(offset, Math.min(offset + 100_000, body.length));
147	    frames.push(`${piece.length.toString(16)}\r\n${piece.toString('latin1')}\r\n`);
148	  }
149	  frames.push('0\r\n\r\n');
