1021	class CdpBrowser {
1022	  private child: ChildProcess;
1023	  private profileDir: string;
1024	  private ws: WebSocket;
1025	  private nextId = 1;
1026	  private pending = new Map<number, { resolve: (v: any) => void; reject: (e: Error) => void; sessionId?: string }>();
1027	  private listeners = new Map<string, (method: string, params: any) => void>();
1028	
1029	  private constructor(child: ChildProcess, profileDir: string, ws: WebSocket) {
1030	    this.child = child;
1031	    this.profileDir = profileDir;
1032	    this.ws = ws;
1033	  }
1034	
1035	  static async launch(): Promise<CdpBrowser> {
1036	    const profileDir = mkdtempSync(join(tmpdir(), 'cartwell-chrome-'));
1037	    const child = spawn(
1038	      CHROME_BIN!,
1039	      [...CHROME_FLAGS, '--remote-debugging-port=0', `--user-data-dir=${profileDir}`, 'about:blank'],
1040	      { stdio: ['ignore', 'ignore', 'pipe'] },
1041	    );
1042	    let stderr = '';
1043	    child.stderr!.setEncoding('utf8');
1044	    child.stderr.on('data', (chunk: string) => { stderr += chunk; });
1045	
1046	    const portFile = join(profileDir, 'DevToolsActivePort');
1047	    const port = await new Promise<string>((resolve, reject) => {
1048	      const started = Date.now();
1049	      const timer = setInterval(() => {
1050	        try {
1051	          const line = readFileSync(portFile, 'utf8').split('\n')[0]!.trim();
1052	          if (line) { clearInterval(timer); resolve(line); }
1053	        } catch {
1054	          if (Date.now() - started > 15_000) {
1055	            clearInterval(timer);
1056	            reject(new Error(`等待 Chrome 调试端口超时：${stderr.slice(-500)}`));
1057	          }
1058	        }
1059	      }, 50);
1060	    });
1061	
1062	    const version = await (await fetch(`http://127.0.0.1:${port}/json/version`)).json();
1063	    const ws = new WebSocket(version.webSocketDebuggerUrl as string);
1064	    await new Promise<void>((resolve, reject) => {
1065	      ws.onopen = (): void => resolve();
1066	      ws.onerror = (): void => reject(new Error('无法连接 Chrome DevTools Protocol'));
1067	    });
1068	
1069	    const browser = new CdpBrowser(child, profileDir, ws);
1070	    ws.onmessage = (event: { data: string }): void => {
1071	      const message: CdpMessage = JSON.parse(event.data);
1072	      if (message.id !== undefined) {
1073	        const entry = browser.pending.get(message.id);
1074	        if (entry && (entry.sessionId === undefined || entry.sessionId === message.sessionId)) {
1075	          browser.pending.delete(message.id);
1076	          if (message.error) entry.reject(new Error(JSON.stringify(message.error)));
1077	          else entry.resolve(message.result);
1078	        }
1079	        return;
1080	      }
1081	      if (message.method && message.sessionId) {
1082	        browser.listeners.get(message.sessionId)?.(message.method, message.params);
1083	      }
1084	    };
1085	    return browser;
1086	  }
1087	
1088	  send(method: string, params: Record<string, unknown> = {}, sessionId?: string): Promise<any> {
1089	    const id = this.nextId++;
1090	    return new Promise((resolve, reject) => {
1091	      this.pending.set(id, { resolve, reject, sessionId });
1092	      this.ws.send(JSON.stringify({ id, method, params, ...(sessionId ? { sessionId } : {}) }));
1093	    });
1094	  }
1095	
1096	  async newPage(url: string): Promise<CdpPage> {
1097	    const { targetId } = await this.send('Target.createTarget', { url: 'about:blank' });
1098	    const { sessionId } = await this.send('Target.attachToTarget', { targetId, flatten: true });
1099	    const page = new CdpPage(this, sessionId);
1100	    this.listeners.set(sessionId, (method, params): void => {
1101	      if (method === 'Fetch.requestPaused') page.handlePaused(params);
1102	    });
1103	    await this.send('Page.enable', {}, sessionId);
1104	    await this.send('Runtime.enable', {}, sessionId);
1105	    // 只拦截新增商品请求：在请求真正发出后暂停，便于核对载荷与提交过程中的按钮状态。
1106	    await this.send('Fetch.enable', {
1107	      patterns: [{ urlPattern: '*/api/products', requestStage: 'Request' }],
1108	    }, sessionId);
1109	    await this.send('Page.navigate', { url }, sessionId);
1110	    await page.waitFor("document.getElementById('product-form') && document.querySelectorAll('#specs [data-spec]').length === 1");
1111	    return page;
1112	  }
1113	
1114	  async close(): Promise<void> {
1115	    try { this.ws.close(); } catch { /* 已关闭 */ }
1116	    this.child.kill('SIGTERM');
1117	    await Promise.race([
1118	      once(this.child, 'exit'),
1119	      new Promise((resolve) => setTimeout(resolve, 3000)),
1120	    ]);
1121	    if (this.child.exitCode === null) this.child.kill('SIGKILL');
1122	    rmSync(this.profileDir, { recursive: true, force: true });
1123	  }
1124	}
