1126	class CdpPage {
1127	  private browser: CdpBrowser;
1128	  private sessionId: string;
1129	  private readonly pausedQueue: any[] = [];
1130	  private readonly pausedWaiters: Array<(params: any) => void> = [];
1131	
1132	  constructor(browser: CdpBrowser, sessionId: string) {
1133	    this.browser = browser;
1134	    this.sessionId = sessionId;
1135	  }
1136	
1137	  handlePaused(params: any): void {
1138	    const waiter = this.pausedWaiters.shift();
1139	    if (waiter) waiter(params);
1140	    else this.pausedQueue.push(params);
1141	  }
1142	
1143	  send(method: string, params: Record<string, unknown> = {}): Promise<any> {
1144	    return this.browser.send(method, params, this.sessionId);
1145	  }
1146	
1147	  async eval(expression: string): Promise<any> {
1148	    const result = await this.send('Runtime.evaluate', {
1149	      expression,
1150	      returnByValue: true,
1151	      awaitPromise: true,
1152	    });
1153	    if (result.exceptionDetails) {
1154	      throw new Error(`页面脚本执行失败：${result.exceptionDetails.text} ${result.exceptionDetails.exception?.description ?? ''}`);
1155	    }
1156	    return result.result.value;
1157	  }
1158	
1159	  // 轮询页面上的布尔条件；提交成功后的整页跳转也会经历短暂的上下文切换，忽略期间的异常。
1160	  async waitFor(expression: string, timeoutMs = 8000, label?: string): Promise<void> {
1161	    const deadline = Date.now() + timeoutMs;
1162	    for (;;) {
1163	      try {
1164	        if (await this.eval(expression)) return;
1165	      } catch {
1166	        if (Date.now() > deadline) throw new Error(`等待页面条件超时：${label ?? expression}`);
1167	      }
1168	      if (Date.now() > deadline) throw new Error(`等待页面条件超时：${label ?? expression}`);
1169	      await new Promise((resolve) => setTimeout(resolve, 50));
1170	    }
1171	  }
1172	
1173	  async waitPaused(timeoutMs = 8000): Promise<any> {
1174	    const queued = this.pausedQueue.shift();
1175	    if (queued) return queued;
1176	    return new Promise((resolve, reject) => {
1177	      const timer = setTimeout(() => {
1178	        const index = this.pausedWaiters.indexOf(resolve as any);
1179	        if (index >= 0) this.pausedWaiters.splice(index, 1);
1180	        reject(new Error('等待新增商品请求被拦截超时'));
1181	      }, timeoutMs);
1182	      this.pausedWaiters.push((params): void => { clearTimeout(timer); resolve(params); });
1183	    });
1184	  }
1185	
1186	  continueRequest(requestId: string): Promise<any> {
1187	    return this.send('Fetch.continueRequest', { requestId });
1188	  }
1189	}
